export const topics=[
{id:'percentages',title:b('Percentages','प्रतिशत'),subject:'quant',icon:'%',color:'purple',exams:['ssc','banking','railways','insurance'],minutes:8,desc:b('Turn “out of 100” into your superpower.','“हर 100 में” को अपनी ताकत बनाएं।'),concept:b('A percentage compares a part to a whole of 100. The whole is the base: changing the base changes the answer.','प्रतिशत किसी भाग की तुलना 100 के आधार से करता है। पूरी मात्रा आधार है: आधार बदलने से उत्तर बदलता है।'),formula:'Part = Whole × Percentage ÷ 100',steps:b(['A bag costs ₹800. Its price increases by 15%. Find the new price.','The base is ₹800. 10% is ₹80 and 5% is ₹40.','The increase is ₹120. Add it to ₹800: the new price is ₹920.','A 15% decrease afterwards uses ₹920 as its base, so it does not reverse the increase.'],['एक बैग की कीमत ₹800 है। कीमत 15% बढ़ती है। नई कीमत ज्ञात करें।','आधार ₹800 है। 10% = ₹80 और 5% = ₹40।','वृद्धि ₹120 है। ₹800 में जोड़ने पर नई कीमत ₹920 है।','इसके बाद 15% की कमी का आधार ₹920 होगा, इसलिए मूल कीमत वापस नहीं आएगी।'])},
{id:'ratios',title:b('Ratio & proportion','अनुपात और समानुपात'),subject:'quant',icon:'a:b',color:'teal',exams:['ssc','banking','railways','insurance'],minutes:7,desc:b('See how parts make a whole.','देखें कि हिस्से मिलकर पूरा कैसे बनाते हैं।'),concept:b('A ratio describes relative sizes. For a:b, there are a+b equal units in total. Scale both parts by the same number to preserve the ratio.','अनुपात सापेक्ष आकार बताता है। a:b में कुल a+b बराबर इकाइयां होती हैं। अनुपात बनाए रखने के लिए दोनों भागों को एक ही संख्या से गुणा करें।'),formula:'One unit = Total ÷ (a + b)',steps:b(['Divide ₹600 between A and B in the ratio 2:3.','Total units = 2 + 3 = 5.','One unit = ₹600 ÷ 5 = ₹120.','A gets 2 × ₹120 = ₹240; B gets 3 × ₹120 = ₹360. Check: ₹240 + ₹360 = ₹600.'],['₹600 को A और B में 2:3 के अनुपात में बांटें।','कुल इकाइयां = 2 + 3 = 5।','एक इकाई = ₹600 ÷ 5 = ₹120।','A को ₹240 और B को ₹360 मिलेंगे। जांच: ₹240 + ₹360 = ₹600।'])},
{id:'work',title:b('Time & work','समय और कार्य'),subject:'quant',icon:'◷',color:'orange',exams:['ssc','banking','railways','insurance'],minutes:9,desc:b('Combine work rates, not completion times.','काम की दरें जोड़ें, समय नहीं।'),concept:b('If A finishes a job in a days, A completes 1/a of the job each day. Independent workers add their rates when working together.','यदि A काम a दिनों में करता है, तो वह प्रतिदिन 1/a काम करता है। साथ काम करने पर स्वतंत्र कामगारों की दरें जुड़ती हैं।'),formula:'Together = 1 ÷ (1/a + 1/b) days',steps:b(['A finishes a job in 12 days and B in 6 days. How long together?','Choose 12 units of work. A does 1 unit/day; B does 2 units/day.','Together they do 3 units/day.','Time = 12 ÷ 3 = 4 days. This is less than either worker’s individual time.'],['A काम 12 दिनों में और B 6 दिनों में करता है। साथ में कितना समय लगेगा?','काम को 12 इकाइयां मानें। A की दर 1 और B की दर 2 इकाई/दिन है।','साथ में दर 3 इकाई/दिन है।','समय = 12 ÷ 3 = 4 दिन। यह दोनों के व्यक्तिगत समय से कम है।'])},
{id:'speed',title:b('Speed & distance','चाल और दूरी'),subject:'quant',icon:'↗',color:'blue',exams:['ssc','banking','railways','insurance'],minutes:8,desc:b('Make distance, speed and time move together.','दूरी, चाल और समय का संबंध समझें।'),concept:b('Speed is distance travelled per unit time. Keep units consistent. For equal distances, average speed is a harmonic mean, not the simple average.','चाल प्रति इकाई समय में तय दूरी है। इकाइयां समान रखें। बराबर दूरियों के लिए औसत चाल साधारण औसत नहीं होती।'),formula:'Distance = Speed × Time',steps:b(['A cyclist travels 18 km at 12 km/h. Find the time.','Time = Distance ÷ Speed.','18 ÷ 12 = 1.5 hours.','0.5 hour = 30 minutes, so the journey takes 1 hour 30 minutes.'],['एक साइकिल सवार 12 किमी/घंटा की चाल से 18 किमी जाता है। समय ज्ञात करें।','समय = दूरी ÷ चाल।','18 ÷ 12 = 1.5 घंटे।','0.5 घंटा = 30 मिनट, इसलिए समय 1 घंटा 30 मिनट है।'])},
{id:'series',title:b('Number series','संख्या श्रृंखला'),subject:'reason',icon:'123',color:'pink',exams:['ssc','banking','railways','insurance'],minutes:6,desc:b('Spot the rule hiding between numbers.','संख्याओं के बीच छिपा नियम पहचानें।'),concept:b('Test simple relationships first: differences, ratios, squares and alternating rules. A finite sequence can fit many rules; these exercises ask for the simplest consistent one.','पहले अंतर, अनुपात, वर्ग और बारी-बारी के नियम जांचें। सीमित श्रृंखला के कई नियम हो सकते हैं; यहां सबसे सरल संगत नियम चुनें।'),formula:'Term(n) = Start + (n − 1) × Step',steps:b(['Find the next term: 4, 9, 16, 25, ?','Differences are 5, 7, 9: consecutive odd numbers.','The next difference is 11. So 25 + 11 = 36.','You can also see squares: 2², 3², 4², 5², 6².'],['अगला पद ज्ञात करें: 4, 9, 16, 25, ?','अंतर 5, 7, 9 हैं: लगातार विषम संख्याएं।','अगला अंतर 11 है। इसलिए 25 + 11 = 36।','ये वर्ग भी हैं: 2², 3², 4², 5², 6²।'])},
{id:'syllogisms',title:b('Syllogisms','न्याय निगमन'),subject:'reason',icon:'◎',color:'indigo',exams:['ssc','banking','insurance'],minutes:9,desc:b('Find what must be true, not what might be.','जो निश्चित है उसे चुनें, केवल संभव को नहीं।'),concept:b('Use only the statements given. “All A are B” puts A inside B; it does not mean all B are A. “Some” guarantees at least one shared member. Universal statements alone do not assert existence.','केवल दिए कथनों का प्रयोग करें। “सभी A, B हैं” में A, B के अंदर है; इसका उल्टा जरूरी नहीं। “कुछ” कम से कम एक सदस्य का अस्तित्व बताता है। केवल “सभी” से अस्तित्व सिद्ध नहीं होता।'),formula:'All A are B ≠ All B are A',steps:b(['All roses are flowers. Some roses are red. What follows?','The red roses exist and belong to the rose set.','Every rose is a flower, so those red roses are also flowers.','Therefore some flowers are red. “All flowers are red” does not follow.'],['सभी गुलाब फूल हैं। कुछ गुलाब लाल हैं। क्या निष्कर्ष निकलेगा?','लाल गुलाबों का अस्तित्व है और वे गुलाब के समूह में हैं।','हर गुलाब फूल है, इसलिए वे लाल गुलाब फूल भी हैं।','इसलिए कुछ फूल लाल हैं। “सभी फूल लाल हैं” निष्कर्ष नहीं निकलता।'])}
];
